import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.BQ1gajhD.js";const f=JSON.parse('{"title":"首钢园","description":"","frontmatter":{},"headers":[],"relativePath":"landmarks/shougang.md","filePath":"landmarks/shougang.md","lastUpdated":1787033866000}'),n={name:"landmarks/shougang.md"};function o(d,t,s,i,h,g){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="首钢园" tabindex="-1">首钢园 <a class="header-anchor" href="#首钢园" aria-label="Permalink to &quot;首钢园&quot;">​</a></h1><p><img src="https://images.unsplash.com/photo-1519925610903-381054cc2a1c?w=1200" alt="首钢园"></p><blockquote><p>&quot;钢铁森林变身科幻之城。&quot;</p></blockquote><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>首钢园位于北京市石景山区，前身是首钢集团的大型钢铁生产基地。北京冬奥会前，这里完成了从&quot;炼钢&quot;到&quot;炼冰&quot;的转型，成为北京冬奥组委办公地和单板滑雪大跳台赛区。如今的首钢园保留了大量高炉、厂房、冷却塔等工业遗存，同时引入体育、会展、科幻、创意等业态，白天是工业风打卡胜地，夜晚灯光亮起宛如科幻电影场景，被网友称为&quot;赛博朋克之城&quot;。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>开放时间</strong></td><td style="text-align:left;">全天开放</td></tr><tr><td style="text-align:left;"><strong>门票价格</strong></td><td style="text-align:left;">免费（部分场馆收费）</td></tr><tr><td style="text-align:left;"><strong>建议游玩</strong></td><td style="text-align:left;">半天</td></tr><tr><td style="text-align:left;"><strong>最佳季节</strong></td><td style="text-align:left;">春秋季，夜晚最佳</td></tr><tr><td style="text-align:left;"><strong>交通方式</strong></td><td style="text-align:left;">地铁6号线或11号线金安桥站，换乘摆渡车</td></tr><tr><td style="text-align:left;"><strong>地址</strong></td><td style="text-align:left;">北京市石景山区石景山路68号</td></tr></tbody></table><h2 id="核心看点" tabindex="-1">核心看点 <a class="header-anchor" href="#核心看点" aria-label="Permalink to &quot;核心看点&quot;">​</a></h2><h3 id="三高炉与老工业遗存" tabindex="-1">三高炉与老工业遗存 <a class="header-anchor" href="#三高炉与老工业遗存" aria-label="Permalink to &quot;三高炉与老工业遗存&quot;">​</a></h3><p>原首钢三号高炉是园区最震撼的工业地标，高炉本体与管道、料仓保存完整，被改造为展览与活动空间，是工业摄影的绝佳题材。</p><h3 id="滑雪大跳台" tabindex="-1">滑雪大跳台 <a class="header-anchor" href="#滑雪大跳台" aria-label="Permalink to &quot;滑雪大跳台&quot;">​</a></h3><p>北京冬奥会首钢滑雪大跳台&quot;雪飞天&quot;坐落于园区内，造型取自敦煌飞天，可远观也可走近感受奥运场馆的气势。</p><h3 id="群明湖与钢铁丛林" tabindex="-1">群明湖与钢铁丛林 <a class="header-anchor" href="#群明湖与钢铁丛林" aria-label="Permalink to &quot;群明湖与钢铁丛林&quot;">​</a></h3><p>园区内的群明湖倒映着高炉与烟囱，湖边的步道与平台是拍摄工业与自然对比景观的好位置。</p><h2 id="游览攻略" tabindex="-1">游览攻略 <a class="header-anchor" href="#游览攻略" aria-label="Permalink to &quot;游览攻略&quot;">​</a></h2><h3 id="推荐路线" tabindex="-1">推荐路线 <a class="header-anchor" href="#推荐路线" aria-label="Permalink to &quot;推荐路线&quot;">​</a></h3><p><strong>半日路线</strong>：</p><p>三高炉 → 群明湖 → 滑雪大跳台 → 空中步道 → 园区咖啡与文创店</p><h3 id="实用贴士" tabindex="-1">实用贴士 <a class="header-anchor" href="#实用贴士" aria-label="Permalink to &quot;实用贴士&quot;">​</a></h3><ol><li><strong>交通</strong>：地铁到金安桥站后可换乘园内摆渡车，园区较大，建议合理规划步行距离</li><li><strong>最佳时间</strong>：傍晚到夜间灯光亮起时最有氛围</li><li><strong>拍照</strong>：高炉、冷却塔、大跳台都是出片点，工业风穿搭更契合场景</li><li><strong>餐饮</strong>：园内有多家咖啡馆与餐厅，六工汇购物中心可供选择</li><li><strong>预约</strong>：部分场馆与展馆需提前预约</li></ol><h3 id="交通方式" tabindex="-1">交通方式 <a class="header-anchor" href="#交通方式" aria-label="Permalink to &quot;交通方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">路线</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>地铁</strong></td><td style="text-align:left;">6号线/11号线金安桥站</td></tr><tr><td style="text-align:left;"><strong>公交</strong></td><td style="text-align:left;">首钢园周边多条公交线路</td></tr><tr><td style="text-align:left;"><strong>自驾</strong></td><td style="text-align:left;">定位&quot;首钢园&quot;，园区设有停车场</td></tr></tbody></table><h2 id="周边景点" tabindex="-1">周边景点 <a class="header-anchor" href="#周边景点" aria-label="Permalink to &quot;周边景点&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">景点</th><th style="text-align:center;">距离</th><th style="text-align:left;">特色</th></tr></thead><tbody><tr><td style="text-align:left;">石景山游乐园</td><td style="text-align:center;">车程10分钟</td><td style="text-align:left;">老牌游乐园</td></tr><tr><td style="text-align:left;">八大处公园</td><td style="text-align:center;">车程15分钟</td><td style="text-align:left;">佛教圣地</td></tr><tr><td style="text-align:left;">园博园</td><td style="text-align:center;">车程20分钟</td><td style="text-align:left;">大型园林景观</td></tr><tr><td style="text-align:left;">北京冬奥公园</td><td style="text-align:center;">步行可达</td><td style="text-align:left;">滨河体育公园</td></tr></tbody></table><h2 id="文化意义" tabindex="-1">文化意义 <a class="header-anchor" href="#文化意义" aria-label="Permalink to &quot;文化意义&quot;">​</a></h2><p>首钢园是城市更新与工业遗产保护的代表性案例。它用冬奥会契机实现了产业转型，把废弃的钢铁厂变成面向公众的文化体育园区，展现了北京城市更新的想象力。</p><hr><p><strong>📍 地址</strong>：北京市石景山区石景山路68号 <strong>🚇 地铁</strong>：6号线/11号线金安桥站</p><p><strong>💡 Tips</strong>：园区很大，建议预留半天时间，穿舒适的鞋，傍晚灯光时分体验最佳。</p>',29)])])}const c=e(n,[["render",o]]);export{f as __pageData,c as default};
